#!/usr/bin/env node
'use strict';
const { cToF } = require('../src/convert.js');
const [cmd, value] = process.argv.slice(2);
const n = Number(value);
if (cmd === 'c2f') {
  console.log(String(cToF(n)));
} else {
  console.error(`unknown command: ${cmd}`);
  process.exit(2);
}

